    solid_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    solid_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 0

    # In the horizontal-bar layout, repeat a motif in the separator only
    # when it occurs at that same tile-column on both sides of the bar.
    if solid_rows:
        rbar = min(solid_rows)
        top = [r for r in range(rbar) if r % pitch == 0]
        bottom = [r for r in range(rbar + len(solid_rows), h) if r % pitch == 0]
        for c0 in range(0, w, pitch):
            # source 4x4 tiles above and below the separator
            above = next((r0 for r0 in reversed(top) if r0 + size <= rbar and
                          any(grid[r0+dr][c0+dc] == 2 for dr in range(size) for dc in range(size) if c0+dc < w)), None)
            below = next((r0 for r0 in bottom if r0 + size <= h and
                          any(grid[r0+dr][c0+dc] == 2 for dr in range(size) for dc in range(size) if c0+dc < w)), None)
            if above is None or below is None or c0 + size > w:
                continue
            a = [grid[above+dr][c0:c0+size] for dr in range(size)]
            b = [grid[below+dr][c0:c0+size] for dr in range(size)]
            if a != b:
                continue
            target = rbar
            if target + size > h:
                continue
            for dr in range(size):
                for dc in range(size):
                    out[target+dr][c0+dc] = a[dr][dc]
            # Highlight the central diagonal marker of a copied tile.
            mr, mc = target + 1, c0 + 1
            if out[mr][mc] == 0:
                out[mr][mc] = 8

    # In the vertical-bar layout, a matching pattern across the barrier is
    # copied into the first corresponding gap position.
    elif solid_cols:
        cbar = min(solid_cols)
        for r0 in range(0, h, pitch):
