    band_rows = [r for r in range(h) if all(grid[r][c] == 3 for c in range(w))]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 0

    # Highlight each existing motif's coordinate-coded cell.
    for tr, r0 in enumerate(range(0, h, pitch)):
        for tc, c0 in enumerate(range(0, w, pitch)):
            rr, cc = r0 + tr, c0 + tc
            if rr < h and cc < w and grid[rr][cc] == 2:
                out[rr][cc] = 8

    # Restore one tile in a horizontal masked band: choose the first lattice
    # column occupied by tiles on both sides of the band, and copy the motif.
    if band_rows:
        rbar = min(band_rows)
        band_end = max(band_rows) + 1
        above_r = rbar - pitch
        below_r = band_end
        if above_r >= 0 and below_r + size <= h:
            above_tiles = []
            below_tiles = []
            for c0 in range(0, w, pitch):
                above_tiles.append(any(grid[above_r + dr][c0 + dc] == 2
