                                       for dr in range(size) for dc in range(size)
                                       if below_r + dr < h and c0 + dc < w))
            common = [tc for tc, (a, b) in enumerate(zip(above_tiles, below_tiles)) if a and b]
            if common:
                tc = common[0]
                c0 = tc * pitch
